/**
 * v2 skill authoring (parallel to v1 `src/agents/skills`, fully standalone so v1
 * can be deleted wholesale once v2 is validated).
 *
 * `skill` emits the platform's skill create envelope **minus the owner**
 * (`ownerId`/`ownerType` injected by the wire client at deploy; the update DTO
 * omits them) with `CatalogRef` tokens at each tool's reference positions.
 *
 * Identity comes from the authoring file's `refName`, exactly like
 * `automation` / `agent`; the owning app comes from the typed
 * `app` reference.
 */
import { slimTokens } from "../../catalog/index.js";
import { deriveSkillInstructions, } from "./input-coverage.js";
/**
 * `name` is a free-text display name, like an agent's — confirmed against
 * the platform's actual create/update path, which only rejects a blank
 * value. Skills created directly in the product commonly use human-readable
 * names (e.g. "Fulfill Punchout Catalog") rather than a slug; a stricter
 * pattern here would reject real, already-deployed data during pull/adopt.
 */
const SKILL_NAME_LENGTH = 64;
function normalizeInputs(inputs) {
    if (inputs === undefined)
        return undefined;
    if (Array.isArray(inputs)) {
        return inputs.map((item) => ({
            name: item.name,
            ...(item.required !== undefined && { required: item.required }),
            ...(item.description !== undefined && { description: item.description }),
        }));
    }
    return Object.entries(inputs).map(([key, value]) => {
        if (typeof value === "string") {
            return { name: key, description: value };
        }
        return {
            name: value.name ?? key,
            ...(value.required !== undefined && { required: value.required }),
            ...(value.description !== undefined && { description: value.description }),
        };
    });
}
function normalizeLookups(lookups) {
    if (lookups === undefined)
        return undefined;
    if (Array.isArray(lookups)) {
        return lookups.map((item) => ({
            input: item.input,
            tool: item.tool,
            ...(item.source !== undefined && { source: item.source }),
        }));
    }
    return Object.entries(lookups).map(([inputKey, value]) => {
        if (typeof value === "string") {
            return { input: inputKey, tool: value };
        }
        return {
            input: inputKey,
            tool: value.tool,
            ...(value.source !== undefined && { source: value.source }),
        };
    });
}
/** Build a v2 skill entity config, exposing `.ref(refName)` and `.def(refName)`. */
export function skill(opts) {
    if (opts.name.length < 1 || opts.name.length > SKILL_NAME_LENGTH) {
        throw new Error(`skill name ${JSON.stringify(opts.name)} must be 1-${SKILL_NAME_LENGTH} characters.`);
    }
    if (opts.discovery?.routingPriority !== undefined &&
        (!Number.isFinite(opts.discovery.routingPriority) ||
            opts.discovery.routingPriority < -100 ||
            opts.discovery.routingPriority > 100)) {
        throw new Error("skill discovery.routingPriority must be a finite number from -100 to 100");
    }
    const normalizedInputs = normalizeInputs(opts.inputs);
    const normalizedLookups = normalizeLookups(opts.lookups);
    const instructions = deriveSkillInstructions(opts.instructions, normalizedInputs, normalizedLookups);
    if (instructions.trim() === "") {
        throw new Error(`skill "${opts.name}" instructions must not be empty (provide instructions or non-empty inputs/lookups).`);
    }
    return {
        ref(refName) {
            return { __kind: "skill", refName, name: opts.name, parent: opts.app.refName };
        },
        def(refName) {
            return {
                kind: "skill",
                parent: opts.app.refName,
                refName,
                // Slim every embedded catalog token to its canonical form (drop barrel bags).
                payload: slimTokens({
                    skill: {
                        name: opts.name,
                        description: opts.description,
                        instructions,
                        status: opts.status ?? "DRAFT",
                        type: "CUSTOM",
                        ...(opts.properties !== undefined ? { properties: opts.properties } : {}),
                        ...(opts.discovery !== undefined ? { discovery: opts.discovery } : {}),
                    },
                    tools: opts.tools ?? [],
                }),
                ...(opts.enabled !== undefined ? { enabled: opts.enabled } : {}),
            };
        },
    };
}
